import sys
import re
import json
import types
import traceback
import warnings

warnings.filterwarnings("ignore", category=SyntaxWarning)

_spiders = {}


def _log(message):
    print(message, flush=True)


def _success(value=None):
    return {"ok": True, "value": value}


def _failure(error_type, message):
    if isinstance(message, dict):
        error = dict(message)
        error.setdefault("type", error_type)
        error.setdefault("traceback", traceback.format_exc())
        return {"ok": False, "error": error}
    return {
        "ok": False,
        "error": {
            "type": error_type,
            "message": message,
            "traceback": traceback.format_exc()
        }
    }


def _begin_request_scope():
    try:
        import requests
        requests._begin_request_scope()
    except Exception:
        pass


def _consume_request_error():
    try:
        import requests
        return requests._consume_transport_error()
    except Exception:
        return None


def _is_empty_content(method, result):
    if isinstance(result, str):
        try:
            result = json.loads(result)
        except Exception:
            return not result
    if not isinstance(result, dict):
        return not result
    if method in ("homeContent", "homeVideoContent"):
        return not result.get("class") and not result.get("list")
    if method in ("categoryContent", "detailContent", "searchContent"):
        return not result.get("list")
    return False


def sanitize_script(script):
    return script


def init_spider(site_key, script_content, ext_param=""):
    _log(f"[spider_runner] init start site={site_key}")
    try:
        module_name = f"spider_{site_key}"
        mod = types.ModuleType(module_name)
        mod.__file__ = f"<{module_name}>"

        clean_content = sanitize_script(script_content)
        exec(compile(clean_content, mod.__file__, "exec"), mod.__dict__)
        _log(f"[spider_runner] exec complete site={site_key}")
        sys.modules[module_name] = mod

        spider_cls = getattr(mod, "Spider", None)
        if spider_cls is None:
            return _failure("ConfigurationError", f"Module {module_name} has no Spider class")

        spider = spider_cls()
        spider.site_key = site_key
        _log(f"[spider_runner] instance created site={site_key}")

        # Inject standard BaseSpider state and helper methods when legacy spiders
        # do not inherit from BaseSpider or call super().__init__().
        from base.spider import Spider as BaseSpider
        base_spider = BaseSpider()
        for attr_name, attr_value in vars(base_spider).items():
            if not hasattr(spider, attr_name):
                setattr(spider, attr_name, attr_value)
        for attr_name in dir(BaseSpider):
            if not attr_name.startswith("__") and not hasattr(spider, attr_name):
                base_val = getattr(BaseSpider, attr_name)
                if callable(base_val):
                    setattr(spider, attr_name, types.MethodType(base_val, spider))
                else:
                    setattr(spider, attr_name, base_val)

        if hasattr(spider, "init"):
            _log(f"[spider_runner] init method start site={site_key}")
            spider.init(ext_param or "")
            _log(f"[spider_runner] init method complete site={site_key}")

        _spiders[site_key] = spider
        _log(f"[spider_runner] init success site={site_key}")
        return _success({"siteKey": site_key})
    except Exception as error:
        return _failure(type(error).__name__, str(error))


def call_spider(site_key, method, args=None):
    _log(f"[spider_runner] call start site={site_key} method={method}")
    try:
        _begin_request_scope()
        spider = _spiders.get(site_key)
        if spider is None:
            return _failure("SessionError", f"Spider for site '{site_key}' is not initialized")

        func = getattr(spider, method, None)
        if func is None or not callable(func):
            # Fallback to snake_case method lookup
            snake_name = re.sub(r'(?<!^)(?=[A-Z])', '_', method).lower()
            func = getattr(spider, snake_name, None)

        if func is None or not callable(func):
            return _failure("MethodError", f"Method '{method}' not found on spider '{site_key}'")

        if isinstance(args, str):
            try:
                args = json.loads(args)
            except Exception:
                args = [args]
        elif args is None:
            args = []

        if isinstance(args, dict):
            result = func(**args)
        elif isinstance(args, list):
            result = func(*args)
        else:
            result = func(args)

        request_error = _consume_request_error()
        if request_error and _is_empty_content(method, result):
            return _failure("RequestException", request_error)

        _log(f"[spider_runner] call complete site={site_key} method={method}")
        return _success(result)
    except Exception as error:
        return _failure(type(error).__name__, str(error))


def destroy_spider(site_key):
    removed = _spiders.pop(site_key, None) is not None
    sys.modules.pop(f"spider_{site_key}", None)
    return _success(removed)
